def _first_int(value: object, keys: tuple[str, ...]) -> int:
    """Return the first non-negative integer-like value from a payload."""
    for key in keys:
        raw = _get_value(value, key)
        if raw is None:
            raw = 0
        try:
            parsed = int(raw)
        except (TypeError, ValueError):
            continue
